```java
interface Shape {            // pure contract: the 'what'
    double area();
}

class Circle implements Shape {     // one 'how'
    private final double r;
    Circle(double r) { this.r = r; }
    public double area() { return Math.PI * r * r; }
}

class Rectangle implements Shape {  // another 'how'
    private final double w, h;
    Rectangle(double w, double h) { this.w = w; this.h = h; }
    public double area() { return w * h; }
}

// Caller depends only on the Shape contract:
double total = 0;
for (Shape s : List.of(new Circle(2), new Rectangle(3, 4)))
    total += s.area(); // no idea which concrete shape it is
```

```java
abstract class Employee {
    private final String name;          // instance state
    Employee(String name) { this.name = name; } // constructor (via super)

    public String getName() { return name; }    // concrete: shared by all
    public abstract double calculatePay();       // abstract: subclasses differ

    public void printPayslip() {                 // template method (concrete)
        System.out.println(name + ": " + calculatePay());
    }
}

class SalariedEmployee extends Employee {
    private final double monthly;
    SalariedEmployee(String n, double m) { super(n); this.monthly = m; }
    public double calculatePay() { return monthly; }
}

// Employee e = new Employee("X"); // COMPILE ERROR: abstract, can't instantiate
Employee e = new SalariedEmployee("Asha", 50000);
e.printPayslip();
```

```java
abstract class Animal {
    abstract String sound();
    Animal() { System.out.println("Animal constructor"); } // runs via super
}

class Dog extends Animal {
    String sound() { return "Woof"; }
}

// Animal a = new Animal();        // COMPILE ERROR: Animal is abstract
Animal a = new Dog();              // OK: concrete subclass

Animal anon = new Animal() {       // OK: anonymous CONCRETE subclass
    String sound() { return "???"; }
};
```
*`new Animal() { ... }` creates an anonymous subclass that implements `sound()` — not the abstract class itself.*

